/** A00-R01-PUN-DETALLE: detalle de punteo, igual para el lado origen (SNNN) y el lado S151. */
public record DetallePunteo(
        int cveReg,                 // 9(02) COMP: solo se conserva el tipo 2 (detalle)
        int libro,                  // en S264 la misma posición es ORIG-264
        long contrato,              // 9(16) COMP; en S264 son SUCTRAN/SUCOPE/PROM/HHMM
        int moneda, int claveTransaccion,
        int tipoMovimiento,         // TM; en S028/S250 se redefine como indicadores
        BigDecimal importe,         // 9(14)V99 COMP -> escala 2
        long autS151, long autAplicacion,
        int sucursalInicial, int cajaInicial,
        int producto, int instrumento,
        byte[] filXAplic) {         // X(09): S404 folio/concepto/movimiento, S501 caja

    /** Llave de agrupación del punteo por totales (orden del SORT SCVETRAN). */
    public LlaveTotales llaveTotales() {
        return new LlaveTotales(libro, moneda, producto, instrumento, claveTransaccion, tipoMovimiento);
    }

    public record LlaveTotales(int libro, int moneda, int producto, int instrumento,
                               int claveTransaccion, int tipoMovimiento)
            implements Comparable<LlaveTotales> {
        private static final Comparator<LlaveTotales> ORDEN = Comparator
                .comparingInt(LlaveTotales::libro).thenComparingInt(LlaveTotales::moneda)
                .thenComparingInt(LlaveTotales::producto).thenComparingInt(LlaveTotales::instrumento)
                .thenComparingInt(LlaveTotales::claveTransaccion).thenComparingInt(LlaveTotales::tipoMovimiento);
        @Override public int compareTo(LlaveTotales o) { return ORDEN.compare(this, o); }
    }
}

/** REG-CVESNNNDIF / REG-CVES151DIF: misma estructura en ambos archivos de diferencias. */
public record DiferenciaPunteo(LlaveDetalle llave,
                               int sucursalInicial, int cajaInicial,
                               int producto, int instrumento, long autAplicacion) {

    /** R01-LLAVE-REGSNNN: contrato de 16 dígitos más clave, importe y autorización S151. */
    public record LlaveDetalle(String contrato,              // 9(16) COMP: String de 16 con ceros
                               int libro, int moneda, int claveTransaccion, int tipoMovimiento,
                               BigDecimal importe,             // 9(14)V99
                               long autS151) implements Comparable<LlaveDetalle> {
        private static final Comparator<LlaveDetalle> ORDEN = Comparator
                .comparing(LlaveDetalle::contrato).thenComparingInt(LlaveDetalle::libro)
                .thenComparingInt(LlaveDetalle::moneda).thenComparingInt(LlaveDetalle::claveTransaccion)
                .thenComparingInt(LlaveDetalle::tipoMovimiento).thenComparing(LlaveDetalle::importe)
                .thenComparingLong(LlaveDetalle::autS151);
        @Override public int compareTo(LlaveDetalle o) { return ORDEN.compare(this, o); }
    }
}

@Configuration
public class PunteoJobConfig {

    /** 000000-PROGRAMA. El parámetro de sistema llega como JobParameter (USING W77-SISTEMA-PARAM). */
    @Bean
    Job punteoS151(JobRepository repo, Step inicio, Step ordenaTotales, Step comparaTotales,
                   Step ordenaPorContrato, Step comparaDetalle, Step purgaTrabajo,
                   Step actualizaB05, JobExecutionDecider hayDiferencias, JobExecutionDecider esAltaDisponibilidad) {
        return new JobBuilder("S151P104", repo)
                .start(inicio).next(ordenaTotales).next(comparaTotales)
                .next(hayDiferencias)                                  // W77-BAN-DIFSNNN = 1 OR W77-BAN-DIFS151 = 1
                    .on("CON_DIFERENCIAS").to(ordenaPorContrato).next(comparaDetalle)
                .from(hayDiferencias)
                    .on("*").to(comparaDetalle)                        // el detalle corre aunque no haya diferencias
                .next(purgaTrabajo)                                    // CLOSE A00-SPUNTEO1/2 WITH PURGE
                .next(esAltaDisponibilidad)                            // sistema 804 o 203 y VALUE OF MYSELF = 0
                    .on("SI").to(actualizaB05)
                .from(esAltaDisponibilidad).on("*").end()
                .end()
                .build();
    }
}

@Bean
Step ordenaTotales(JobRepository repo, PlatformTransactionManager tx,
                   @Qualifier("cvetran") FlatFileItemReader<DetallePunteo> origen,
                   SortedWorkFileWriter<DetallePunteo> spunteo1) {
    // 20010-GENERA-ARCHIVO1 + SORT SCVETRAN ... USING A00-SPUNTEO1 GIVING A00-SPUNTEO1
    return new StepBuilder("ordenaTotales", repo)
            .<DetallePunteo, DetallePunteo>chunk(1000, tx)
            .reader(origen)
            .processor(d -> d.cveReg() == 2 ? d : null)        // IF A00-R01-PUN-CVEREG = 2: header y trailer se descartan
            .writer(spunteo1.ordenadoPor(Comparator.comparing(DetallePunteo::llaveTotales)))
            .build();
}
// El lado S151 (CVETRANS151 -> A00-SPUNTEO2) usa el mismo step con otro reader y otro archivo de trabajo.

/** 30300-COMPARA-GLOBAL: merge de dos secuencias de totales ya agrupadas por LlaveTotales. */
public ResultadoPunteo comparaTotales(PeekingIterator<GrupoTotales> snnn,
                                      PeekingIterator<GrupoTotales> s151) {
    var r = new ResultadoPunteo();
    while (snnn.hasNext() || s151.hasNext()) {
        if (!s151.hasNext()) { r.soloOrigen(snnn.next()); continue; }          // DET4
        if (!snnn.hasNext()) { r.soloS151(s151.next());   continue; }          // DET3

        int cmp = snnn.peek().llave().compareTo(s151.peek().llave());
        if (cmp == 0) {
            GrupoTotales a = snnn.next(), b = s151.next();
            if (a.importe().compareTo(b.importe()) == 0) r.cuadra(a, b);        // DET1
            else { r.descuadre(a, b); }                                          // DET2: graba en ambos archivos
        } else if (cmp > 0) {
            r.soloS151(s151.next());                                            // DET3 -> CVES151DIF
        } else {
            r.soloOrigen(snnn.next());                                          // DET4 -> CVESNNNDIF
        }
    }
    return r;   // r.hayDiferenciaOrigen() = W77-BAN-DIFSNNN; r.hayDiferenciaS151() = W77-BAN-DIFS151
}

/** 30600/30700: relee el grupo descuadrado y escribe cada movimiento en CVESNNNDIF. */
void grabaDiferenciasOrigen(GrupoTotales grupo, ItemWriter<DiferenciaPunteo> cvesnnndif) throws Exception {
    banderaDiferenciaOrigen = true;                               // MOVE 1 TO W77-BAN-DIFSNNN
    // SEEK + PERFORM VARYING W77-APUCVE FROM RANGO1 UNTIL > RANGO2: el grupo ya está en memoria.
    var difs = grupo.movimientos().stream()
            .map(m -> DiferenciaPunteo.de(m, m.cajaInicial()))
            .toList();
    cvesnnndif.write(new Chunk<>(difs));
    // IF W77-EOF = 0 OR 1 en el fuente: siempre verdadero, se escribe sin condición.
}

/** 30800/30900: lado S151. */
void grabaDiferenciasS151(GrupoTotales grupo, ItemWriter<DiferenciaPunteo> cves151dif,
                          DetallePunteo ultimoOrigenLeido, P104Properties props) throws Exception {
    banderaDiferenciaS151 = true;                                 // MOVE 1 TO W77-BAN-DIFS151
    var difs = grupo.movimientos().stream()
            .map(m -> DiferenciaPunteo.de(m,
                    props.compatibilidadCajaOrigen()               // p104.compatibilidad-caja-origen: true
                        ? ultimoOrigenLeido.cajaInicial()          // MOVE A00-R01-PUN-CAJAINI (buffer del lado origen)
                        : m.cajaInicial()))                        // R00-S151-CAJAINI: el valor correcto
            .toList();
    cves151dif.write(new Chunk<>(difs));
}

/** 50100-COMPARA-DETALLE: merge de CVESNNNDIF y CVES151DIF ordenados por LlaveDetalle. */
void comparaDetalle(PeekingIterator<DiferenciaPunteo> snnn, PeekingIterator<DiferenciaPunteo> s151,
                    ReportePunteoDetalle reporte) {
    while (snnn.hasNext() || s151.hasNext()) {
        if (!s151.hasNext()) { reporte.faltaEnS151(snnn.next()); continue; }    // DET2
        if (!snnn.hasNext()) { reporte.faltaEnOrigen(s151.next()); continue; }  // DET1
        int cmp = snnn.peek().llave().compareTo(s151.peek().llave());
        if (cmp == 0) {
            snnn.next(); s151.next();          // casan: no se imprimen (PERFORM 50500 comentado)
        } else if (cmp > 0) {
            reporte.faltaEnOrigen(s151.next());
        } else {
            reporte.faltaEnS151(snnn.next());
        }
    }
}

@Component
@RequiredArgsConstructor
public class ControlB05Tasklet implements Tasklet {      // 010000-VERIFICA-B05

    private final B05ProcesosRepository b05;            // B05PROCESOS IN S151LIBCONTROL
    private final P104Properties props;                 // numero-proceso: 104

    @Override
    @Transactional
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        var llave = new B05Id(sistema(ctx), fechaProcesoS151(ctx), props.numeroProceso());
        b05.findById(llave).ifPresentOrElse(reg -> {
            if (reg.estatusPrograma() != 0) {
                // STOP RUN: el fuente termina sin mensaje; aquí se termina el job explícitamente.
                c.getStepExecution().setTerminateOnly();
                c.setExitStatus(new ExitStatus("YA_PROCESADO"));
            }
        }, () -> b05.save(B05Proceso.nuevo(llave)));      // 010100-CREA-B05 (función 19)
        return RepeatStatus.FINISHED;
    }
}
